-- mod-classless-wildcard: forged spells, generated by
-- data/sql/generators/gen_forged_spells.py. Do not hand-edit.
-- Requires a worldserver restart.

CREATE TABLE IF NOT EXISTS `cw_forged_spells` (
  `first_spell` INT UNSIGNED NOT NULL COMMENT 'rank 1 of the forged line',
  `recipe`      VARCHAR(48) NOT NULL COMMENT 'the recipe key, for tracing',
  `rarity`      TINYINT UNSIGNED NOT NULL DEFAULT 255 COMMENT '255 = derive from power',
  `enabled`     TINYINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`first_spell`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Classless forged spells';

CREATE TABLE IF NOT EXISTS `cw_forged_meta` (
  `key`   VARCHAR(32) NOT NULL,
  `value` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Which generator run the forged rows came from';

-- The Hero skill line. Both rows are load-bearing: without the
-- skillline_dbc row GetSkillRangeType returns SKILL_RANGE_NONE, and
-- without the skillraceclassinfo_dbc row _LoadSkills deletes the skill
-- at every login.
DELETE FROM `skillline_dbc` WHERE `ID` = 990;

DELETE FROM `skillraceclassinfo_dbc` WHERE `ID` = 990500;

DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 960000 AND 962047;
DELETE FROM `skilllineability_dbc` WHERE `Spell` BETWEEN 960000 AND 962047;
DELETE FROM `spell_ranks` WHERE `first_spell_id` BETWEEN 960000 AND 962047;
DELETE FROM `cw_forged_spells` WHERE `first_spell` BETWEEN 960000 AND 962047;




DELETE FROM `spell_script_names` WHERE `spell_id` BETWEEN 960000 AND 962047;


